sys_script_include.script:
var BaseValidatorUtils = Class.create();
BaseValidatorUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    checkDuplicateName: function() {
        var name = this.getParameter("sysparm_base_name");
        if (!name) {
            return "";
        }

        var normalizedInput = name.trim().toLowerCase();

        var base = new GlideRecord('x_2060759_base_m_0_bases');
        base.query();

        while (base.next()) {
            var existingName = base.getValue("name");
            if (existingName && existingName.trim().toLowerCase() === normalizedInput) {
                return "true";
            }
        }
        return "false";
    },

    checkDuplicateCityState: function() {
        var city = this.getParameter("sysparm_city");
        var state = this.getParameter("sysparm_state");

        if (!city || !state) {
            return "";
        }

        var normalizedCity = city.trim().toLowerCase();
        var normalizedState = state.trim().toLowerCase();

        var base = new GlideRecord("x_2060759_base_m_0_bases");
        base.query();

        while (base.next()) {
            var existingCity = base.getValue("city");
            var existingState = base.getValue("state");

            if (!existingCity || !existingState) continue;

            if (
                existingCity.trim().toLowerCase() === normalizedCity &&
                existingState.trim().toLowerCase() === normalizedState
            ) {
                return "true";
            }
        }
        return "false";
    },

    checkDuplicateManager: function() {
        var manager = this.getParameter("sysparm_manager");

        if (!manager) {
            return "";
        }

        var base = new GlideRecord("x_2060759_base_m_0_bases");
        base.addQuery("manager", manager);
        base.query();

        if (base.hasNext()) {
            return "true";
        }
        return "false";
    },

    type: 'BaseValidatorUtils'
});
